cat > /tmp/repro.py <<'EOF'
import attr
import pytest

def test_error_message():
    try:
        @attr.s
        class MyClass:
            # Both type annotation and type argument (type=int)
            x: str = attr.ib(type=int)
    except ValueError as e:
        assert "Type annotation and type argument cannot both be present for 'x'" in str(e)
        return

    pytest.fail("ValueError not raised")

if __name__ == "__main__":
    try:
        test_error_message()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        exit(1)
EOF
